1	import { getDb } from './db'
2	import {
3	  DEFAULT_SETTINGS,
4	  type LegacySettingsFields,
5	  type SettingsRecord,
6	} from './settings-types'
7	import {
8	  buildDefaultProfile,
9	  ensureAtLeastOneProfile,
10	  getProfile,
11	  listProfiles,
12	  saveProfile,
13	  DEFAULT_PROFILE_NAME,
14	  type ProfileRecord,
15	} from './profiles'
16	import type { DrillConfig } from '../engine/types'
17	
18	export { DEFAULT_SETTINGS, type SettingsRecord } from './settings-types'
19	
20	export async function loadSettings(): Promise<SettingsRecord> {
21	  const db = getDb()
22	  if (!db) return DEFAULT_SETTINGS
23	  try {
24	    const row = await db.settings.get('singleton')
25	    if (!row) return DEFAULT_SETTINGS
26	    // Strip any legacy drill fields when returning to callers.
27	    const { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId } = {
28	      ...DEFAULT_SETTINGS,
29	      ...row,
30	    }
31	    return { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId }
32	  } catch {
33	    return DEFAULT_SETTINGS
34	  }
35	}
36	
37	export async function saveSettings(s: SettingsRecord): Promise<void> {
38	  const db = getDb()
39	  if (!db) return
40	  try {
41	    // Only write the slim shape — never re-persist legacy drill fields.
42	    const { id, commitKeyCode, commitKeyLabel, inputSource, activeProfileId } = s
43	    await db.settings.put({
44	      id,
45	      commitKeyCode,
46	      commitKeyLabel,
47	      inputSource,
48	      ...(activeProfileId !== undefined ? { activeProfileId } : {}),
49	    })
50	  } catch {
51	    /* ignore */
52	  }
53	}
54	
55	let inFlightActive: Promise<ProfileRecord> | null = null
56	
57	async function readLegacySettingsOverrides(): Promise<Partial<DrillConfig>> {
58	  const db = getDb()
59	  if (!db) return {}
60	  try {
61	    const row = (await db.settings.get('singleton')) as
62	      | (SettingsRecord & LegacySettingsFields)
63	      | undefined
64	    if (!row) return {}
65	    const overrides: Partial<DrillConfig> = {}
66	    const copyNumber = (k: keyof LegacySettingsFields, target: keyof DrillConfig) => {
67	      const v = row[k]
68	      if (typeof v === 'number') (overrides[target] as number) = v
69	    }
70	    const copyBool = (k: keyof LegacySettingsFields, target: keyof DrillConfig) => {
71	      const v = row[k]
72	      if (typeof v === 'boolean') (overrides[target] as boolean) = v
73	    }
74	    copyNumber('preCueMinMs', 'preCueMinMs')
75	    copyNumber('preCueMaxMs', 'preCueMaxMs')
76	    copyNumber('rounds', 'rounds')
77	    copyNumber('workMs', 'workMs')
78	    copyNumber('restMs', 'restMs')
79	    copyNumber('perFalseStartPenalty', 'perFalseStartPenalty')
80	    copyNumber('perHesitationPenalty', 'perHesitationPenalty')
81	    copyBool('penaltyCounterEnabled', 'penaltyCounterEnabled')
82	    copyBool('distanceAxisEnabled', 'distanceAxisEnabled')
83	    copyBool('audioToneEnabled', 'audioToneEnabled')
84	    copyBool('textOverlayEnabled', 'textOverlayEnabled')
85	    return overrides
86	  } catch {
87	    return {}
88	  }
89	}
90	
91	/**
92	 * Resolve the user's active drill profile. On first run (or after migrating
93	 * from Phase 2/3) seeds a Default profile from whatever drill-config-shaped
94	 * fields the legacy SettingsRecord carried, then persists `activeProfileId`.
95	 *
96	 * Concurrent callers share one in-flight promise so we never double-seed under
97	 * React StrictMode's double-mount.
98	 */
99	export function loadActiveProfile(): Promise<ProfileRecord> {
100	  if (inFlightActive) return inFlightActive
101	  inFlightActive = (async () => {
102	    try {
103	      const settings = await loadSettings()
104	      if (settings.activeProfileId) {
105	        const existing = await getProfile(settings.activeProfileId)
106	        if (existing) return existing
107	      }
108	      const existing = await listProfiles()
109	      if (existing.length > 0) {
110	        const named =
111	          existing.find((p) => p.name === DEFAULT_PROFILE_NAME) ?? existing[0]
112	        await saveSettings({ ...settings, activeProfileId: named.id })
113	        return named
114	      }
115	      const overrides = await readLegacySettingsOverrides()
116	      const seed = buildDefaultProfile(overrides)
117	      await saveProfile(seed)
118	      await saveSettings({ ...settings, activeProfileId: seed.id })
119	      return seed
120	    } finally {
121	      inFlightActive = null
122	    }
123	  })()
124	  return inFlightActive
125	}
126	
127	export async function setActiveProfile(id: string): Promise<void> {
128	  const settings = await loadSettings()
129	  await saveSettings({ ...settings, activeProfileId: id })
130	}
131	
132	export { ensureAtLeastOneProfile }
