1	import Dexie, { type EntityTable } from 'dexie'
2	import type { RepRecord, SessionRecord } from '../engine/types'
3	import type { SettingsRecord } from './settings-types'
4	import type { ProfileRecord } from './profiles'
5	
6	export class ReactorDB extends Dexie {
7	  sessions!: EntityTable<SessionRecord, 'id'>
8	  reps!: EntityTable<RepRecord, 'id'>
9	  settings!: EntityTable<SettingsRecord, 'id'>
10	  profiles!: EntityTable<ProfileRecord, 'id'>
11	
12	  constructor() {
13	    super('pointfight-reactor')
14	    this.version(1).stores({
15	      sessions: 'id, startedAt',
16	      reps: 'id, sessionId, cueId',
17	    })
18	    this.version(2).stores({
19	      sessions: 'id, startedAt',
20	      reps: 'id, sessionId, cueId',
21	      settings: 'id',
22	    })
23	    this.version(3).stores({
24	      sessions: 'id, startedAt',
25	      reps: 'id, sessionId, cueId',
26	      settings: 'id',
27	      profiles: 'id, createdAt',
28	    })
29	  }
30	}
31	
32	let _db: ReactorDB | null = null
33	let _openError: Error | null = null
34	
35	export function getDb(): ReactorDB | null {
36	  if (_db) return _db
37	  if (_openError) return null
38	  try {
39	    _db = new ReactorDB()
40	    return _db
41	  } catch (err) {
42	    _openError = err instanceof Error ? err : new Error(String(err))
43	    return null
44	  }
45	}
46	
47	export function getDbError(): Error | null {
48	  return _openError
49	}
50	
51	export async function saveSession(session: SessionRecord): Promise<void> {
52	  const db = getDb()
53	  if (!db) return
54	  try {
55	    await db.sessions.put(session)
56	  } catch (err) {
57	    _openError = err instanceof Error ? err : new Error(String(err))
58	  }
59	}
60	
61	export async function saveRep(rep: RepRecord): Promise<void> {
62	  const db = getDb()
63	  if (!db) return
64	  try {
65	    await db.reps.put(rep)
66	  } catch (err) {
67	    _openError = err instanceof Error ? err : new Error(String(err))
68	  }
69	}
70	
71	export async function listRecentSessions(limit = 20): Promise<SessionRecord[]> {
72	  const db = getDb()
73	  if (!db) return []
74	  try {
75	    return await db.sessions
76	      .orderBy('startedAt')
77	      .reverse()
78	      .limit(limit)
79	      .toArray()
80	  } catch {
81	    return []
82	  }
83	}
84	
85	/**
86	 * Bulk-fetch reps for a set of sessionIds, grouped by sessionId. Sessions in
87	 * `sessionIds` that have no reps still appear in the result with an empty
88	 * array — callers can rely on Map.get(id) returning [], not undefined.
89	 */
90	export async function listRepsForSessions(
91	  sessionIds: string[],
92	): Promise<Map<string, RepRecord[]>> {
93	  const out = new Map<string, RepRecord[]>()
94	  for (const id of sessionIds) out.set(id, [])
95	  if (sessionIds.length === 0) return out
96	  const db = getDb()
97	  if (!db) return out
98	  try {
99	    const reps = await db.reps.where('sessionId').anyOf(sessionIds).toArray()
100	    for (const r of reps) {
101	      const list = out.get(r.sessionId)
102	      if (list) list.push(r)
103	    }
104	  } catch {
105	    /* fall through with whatever was groupable */
106	  }
107	  return out
108	}
